#!/bin/bash
# archive_copy <dir> <archive dir> <name> <stamp>: copy name.1 to <archive dir>/name.<stamp>.
archive_copy() {
  local dir=$1 archive=$2 name=$3 stamp=$4
  mkdir -p "$archive"
  cp "$dir/$name.1" "$archive/$name.$stamp"
}

lib/prune.sh.text:
#!/bin/bash
# prune_local <dir> <name> <keep>: delete name.N with N > keep.
prune_local() {
  local dir=$1 name=$2 keep=$3 f n
  for f in "$dir/$name".*; do
    [ -e "$f" ] || continue
    n=${f##*.}
    case $n in ''|*[!0-9]*) continue ;; esac
    [ "$n" -gt "$keep" ] && rm -f -- "$f"
  done
}
# prune_archive <archive dir> <name> <keep>: keep only the newest <keep> name.<stamp>.
prune_archive() {
  local archive=$1 name=$2 keep=$3 f
  for f in $(ls "$archive" | grep -E "^$name\.[0-9]{8}$" | sort -r | tail -n +$((keep + 1))); do
    rm -f -- "$archive/$f"
  done
}

