#!/bin/bash
# read_keep <conf>: print keep value (must be a positive integer).
read_keep() {
  local k
  k=$(sed -n 's/^keep=\([0-9][0-9]*\)$/\1/p' "$1" | tail -n 1)
  [ -n "$k" ] && [ "$k" -ge 1 ] || { echo "invalid keep in $1" >&2; return 1; }
  echo "$k"
}
# prune_local <dir> <name> <keep>: remove name.N where N > keep.
prune_local() {
  local dir=$1 name=$2 keep=$3 f n
  for f in "$dir/$name".*; do
    [ -e "$f" ] || continue
    n=${f##*.}
    case $n in ''|*[!0-9]*) continue;; esac
    [ "$n" -gt "$keep" ] && rm -f -- "$f"
  done
}
# prune_archive <archive dir> <name> <keep>: keep newest <keep> name.<8-digit date>.
prune_archive() {
  local archive=$1 name=$2 keep=$3 f n i=0
  for f in $(for g in "$archive/$name".*; do
      [ -e "$g" ] || continue
      n=${g##*.}
      case $n in [0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]) echo "$n";; esac
    done | sort -r); do
    i=$((i + 1))
    [ "$i" -gt "$keep" ] && rm -f -- "$archive/$name.$f"
  done
}

