#!/bin/bash
# read_keep: print keep from config (ROTATE_CONF or config/rotate.conf). Fails unless it is a positive integer.
read_keep() {
  local conf=${ROTATE_CONF:-$root/config/rotate.conf} keep
  keep=$(sed -n 's/^keep=//p' "$conf" 2>/dev/null | tail -n 1)
  case "$keep" in
    ''|*[!0-9]*|0) echo "rotate: invalid or missing keep in $conf" >&2; return 1 ;;
  esac
  echo "$keep"
}

# prune_local <dir> <name> <keep>: delete name.N (digits only) with N > keep. Lower N = newer.
prune_local() {
  local dir=$1 name=$2 keep=$3 f suffix
  for f in "$dir/$name".*; do
    [ -f "$f" ] || continue
    suffix=${f#"$dir/$name".}
    case "$suffix" in ''|*[!0-9]*) continue ;; esac
    [ "$((10#$suffix))" -gt "$keep" ] && rm -f -- "$f"
  done
}

# prune_archive <archive dir> <name> <keep>: keep only the newest <keep> name.<YYYYMMDD>, delete the rest.
prune_archive() {
  local archive=$1 name=$2 keep=$3 f suffix
  for f in "$archive/$name".*; do
    [ -f "$f" ] || continue
    suffix=${f#"$archive/$name".}
    case "$suffix" in [0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]) echo "$suffix" ;; esac
  done | sort -r | tail -n +"$((keep + 1))" | while read -r suffix; do
    rm -f -- "$archive/$name.$suffix"
  done
}

